diff --git a/internal/cache/visits.go b/internal/cache/visits.go
--- a/internal/cache/visits.go
+++ b/internal/cache/visits.go
@@ -1,7 +1,16 @@
 package cache
+
+import "net/http"

 var visits = map[string]int{}

 func Count(path string) int {
 	return visits[path]
 }
+
+func Middleware(next http.Handler) http.Handler {
+	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		visits[r.URL.Path]++
+		next.ServeHTTP(w, r)
+	})
+}
